#!/usr/bin/env bash
# deploy-readmes.sh: copy A2_repo-readmes/dist/<repo>/README.{html,canvas} to the root of each child clone and commit ONLY those two files.
#   deploy-readmes.sh          for every non-archived repo of the registry with a clone under $BASE (profile + Pages repos held):
#                              copy (README.html gets a "generated by" comment after the doctype, README.canvas is a byte copy),
#                              stage the two files by explicit path, commit, then pull --no-rebase and push origin main.
#   deploy-readmes.sh --check  change nothing; exit 1 when a deployed copy differs from dist (or is missing).
# Env: BASE (clone root, default: parent of this repo), NO_PUSH=1 (commit only), ONLY="name name" (restrict to those GitHub names).
# README.md is never touched. HOLD_PUSH repos are committed locally and never pushed (their pushes start deploy chains).
[ -n "${BASH_VERSION:-}" ] || exec bash "$0" "$@"
set -u
HERE="$(cd "$(dirname "$0")" && pwd)"
HOME_REPO="$(cd "$HERE/.." && pwd)"
export BASE="${BASE:-$(cd "$HOME_REPO/.." && pwd)}"
DIST="${DIST:-$HERE/dist}"
PRIV="$(mktemp -d)"; trap 'rm -rf "$PRIV"' EXIT   # private repos'"'"' pages: rendered here (outside master), deployed only to that private clone
OUT="$PRIV" node "$HOME_REPO/0_registry/render-repo-readmes.js" --private >/dev/null || { echo "deploy-readmes: private render failed"; exit 1; }
src_of() { [ -f "$PRIV/$1/README.html" ] && echo "$PRIV" || echo "$DIST"; }
MSG="${MSG:-README.html + README.canvas: generated from _git-repos-master/A2_repo-readmes}"
TRAILER='Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_0172rQF2sCRHaeMtr1E7pzQ8'
HOLD_PUSH=" cloudy-t-infra cloudy-u-containers "
NOTE='generated by _git-repos-master build.sh (A2_repo-readmes) - do not edit; edit the sources in _git-repos-master and run A2_repo-readmes/deploy-readmes.sh'

stamp() { awk -v n="<!-- $NOTE -->" '{ print } NR == 1 { print n }' "$1"; } # html: note after the doctype

list() { node "$HOME_REPO/0_registry/render-repo-readmes.js" --list | while IFS=$'\t' read -r name dir; do
  [ -n "${ONLY:-}" ] && case " $ONLY " in *" $name "*) ;; *) continue ;; esac; printf '%s\t%s\n' "$name" "$dir"; done; }

if [ "${1:-}" = "--check" ]; then
  bad=0; n=0
  while IFS=$'\t' read -r name dir; do
    n=$((n+1))
    cmp -s <(stamp "$(src_of "$name")/$name/README.html") "$dir/README.html" || { echo "DRIFT $name: README.html"; bad=1; }
    cmp -s "$(src_of "$name")/$name/README.canvas" "$dir/README.canvas" || { echo "DRIFT $name: README.canvas"; bad=1; }
  done < <(list)
  [ $bad = 0 ] && echo "deploy-readmes --check: clean ($n repos)" || echo "deploy-readmes --check: DRIFT"
  exit $bad
fi

ok=0; pushed=0; held=""; fail=""
while IFS=$'\t' read -r name d; do
  S="$(src_of "$name")"
  [ -f "$S/$name/README.html" ] || { fail="$fail $name(no-dist)"; continue; }
  stamp "$S/$name/README.html" > "$d/README.html.tmp.$$" && mv "$d/README.html.tmp.$$" "$d/README.html" || { fail="$fail $name(copy)"; continue; }
  cp "$S/$name/README.canvas" "$d/README.canvas" || { fail="$fail $name(copy)"; continue; }
  paths=(README.html README.canvas)
  git -C "$d" add --sparse -- "${paths[@]}" 2>/dev/null
  if ! git -C "$d" diff --cached --quiet -- "${paths[@]}"; then
    git -C "$d" commit -q -m "$MSG

$TRAILER" -- "${paths[@]}" >/dev/null 2>&1 || { fail="$fail $name(commit)"; continue; }
  fi
  ok=$((ok+1))
  [ "${NO_PUSH:-}" = 1 ] && continue
  case "$HOLD_PUSH" in *" $name "*) held="$held $name"; continue ;; esac
  [ -n "$(git -C "$d" log origin/main..HEAD --oneline 2>/dev/null)" ] || continue   # nothing unpushed
  git -C "$d" pull -q --no-rebase --no-edit origin main >/dev/null 2>&1
  if git -C "$d" push -q origin main >/dev/null 2>&1; then pushed=$((pushed+1)); else fail="$fail $name(push)"; fi
done < <(list)
echo "deploy-readmes: ok=$ok pushed=$pushed held=[${held# }] fail=[${fail# }]"
[ -z "$fail" ]
